// Extract faceted search parameters
const query = $input.item.json.query;
const facetFields = $input.item.json.facet_fields || ['document_type', 'department'];
const limit = $input.item.json.limit || 10;
const minScore = $input.item.json.min_score || 0.7;
const conversationId = $input.item.json.conversation_id;

if (!query) {
  throw new Error('query is required');
}

return {
  query,
  facetFields,
  limit,
  minScore,
  conversationId,
  timestamp: new Date().toISOString()
};

// Format faceted search results for MS Teams
const results = $input.item.json.results || [];
const facets = $input.item.json.facets || {};
const metadata = $input.item.json.metadata || {};

let message = `**Faceted Search Results**\n\n`;
message += `Query: "${metadata.query || 'N/A'}"\n`;
message += `Total Results: ${metadata.total_results || 0}\n\n`;

// Show facet breakdown
if (Object.keys(facets).length > 0) {
  message += `**📊 Facet Breakdown:**\n\n`;

  for (const [field, counts] of Object.entries(facets)) {
    message += `**${field}:**\n`;
    const sortedCounts = Object.entries(counts).sort((a, b) => b[1] - a[1]);
    for (const [value, count] of sortedCounts) {
      message += `  • ${value}: ${count}\n`;
    }
    message += '\n';
  }
  message += '---\n\n';
}

// Show top results
if (results.length === 0) {
  message += '⚠️ No matching documents found.\n';
} else {
  message += `**Top ${results.length} Results:**\n\n`;
  results.forEach((result, index) => {
    message += `**${index + 1}. ${result.file_name || 'Unknown'}**\n`;
    message += `📄 Score: ${(result.score || 0).toFixed(3)}\n`;

    if (result.document_type) {
      message += `📑 Type: ${result.document_type}\n`;
    }
    if (result.department) {
      message += `🏢 Department: ${result.department}\n`;
    }

    if (result.text) {
      const preview = result.text.substring(0, 120);
      message += `\n${preview}${result.text.length > 120 ? '...' : ''}\n`;
    }

    message += '\n';
  });
}

return {
  message,
  conversation_id: $input.item.json.conversation_id
};

// Return formatted response
return {
  json: {
    success: true,
    message: $json.message,
    conversation_id: $json.conversation_id
  }
};
